from typing import List, Sequence

def fisher_matrix(p: Sequence[float], score: Sequence[Sequence[float]]) -> List[List[float]]:
    """Fisher information matrix G[i][j] = sum_x p[x]*score[x][i]*score[x][j]."""
    n = len(p)
    d = len(score[0]) if n > 0 else 0
    return [[sum(p[x]*score[x][i]*score[x][j] for x in range(n))
             for j in range(d)] for i in range(d)]

def quadratic_form(G: Sequence[Sequence[float]], v: Sequence[float]) -> float:
    d = len(v)
    return sum(v[i]*G[i][j]*v[j] for i in range(d) for j in range(d))

def quadratic_form_sumsquares(p, score, v) -> float:
    n, d = len(p), len(v)
    return sum(p[x]*(sum(v[i]*score[x][i] for i in range(d)))**2 for x in range(n))

if __name__ == "__main__":
    p = [0.2, 0.5, 0.3]
    raw = [[1.0, -2.0], [0.5, 1.0], [-1.0, 0.4]]
    means = [sum(p[x]*raw[x][i] for x in range(3)) for i in range(2)]
    score = [[raw[x][i]-means[i] for i in range(2)] for x in range(3)]
    G = fisher_matrix(p, score)
    print("Fisher matrix:", G)
    print("symmetric:", abs(G[0][1]-G[1][0]) < 1e-12)
    for v in ([1.0,0.0],[0.3,-0.7],[-1.2,2.1]):
        print(v, quadratic_form(G,v), quadratic_form_sumsquares(p,score,v))

import math
from typing import Callable

def bernoulli_fisher(s: float) -> float:
    """Closed-form Bernoulli Fisher information: 1/(s(1-s))."""
    return 1.0/(s*(1.0-s))

def kl_between_bernoulli(s: float, t: float) -> float:
    return s*math.log(s/t) + (1.0-s)*math.log((1.0-s)/(1.0-t))

def second_derivative(f: Callable[[float], float], x: float, h: float = 1e-4) -> float:
    return (f(x+h) - 2.0*f(x) + f(x-h))/(h*h)

if __name__ == "__main__":
    for s in (0.1, 0.25, 0.5, 0.75, 0.9, 0.98):
        closed = bernoulli_fisher(s)
        curv = second_derivative(lambda t: kl_between_bernoulli(s, t), s)
        print(f"s={s:.2f}  1/(s(1-s))={closed:.4f}  d2KL={curv:.4f}")

