function FISHER_MATRIX(p[0..n-1], score[0..n-1][0..d-1]):
    G <- d x d zero matrix
    for x in 0..n-1:
        for i in 0..d-1:
            psi <- p[x]*score[x][i]
            for j in 0..d-1:
                G[i][j] <- G[i][j] + psi*score[x][j]
    return G

function FISHER_QUADRATIC_FORM(p, score, v):
    total <- 0
    for x in 0..n-1:
        sv <- sum_i v[i]*score[x][i]      # directional score
        total <- total + p[x]*sv*sv
    return total

function KL_DIVERGENCE(p, q):
    total <- 0
    for x in 0..n-1:
        total <- total + p[x]*log(p[x]/q[x])
    return total

function FISHER_VIA_KL_CURVATURE(p_of, theta, h):
    p0 <- p_of(theta)
    define KL_TO(t):
        pt <- p_of(t)
        return sum_x p0[x]*log(p0[x]/pt[x])
    return (KL_TO(theta+h) - 2*KL_TO(theta) + KL_TO(theta-h)) / h^2
